"""Retirement entries must authenticate deleted generated bytes."""

import hashlib
import importlib.util
import os
import subprocess
from pathlib import Path

import pytest
import yaml

ROOT = Path(__file__).resolve().parents[2]
SCRIPT = ROOT / "scripts/maintenance/verify_repo_structure.py"


def run(repo, *args):
    env = {key: value for key, value in os.environ.items()
           if key not in {"GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR", "GIT_INDEX_FILE"}}
    return subprocess.run(["git", *args], cwd=repo, env=env, check=True,
                          capture_output=True).stdout


def checker():
    spec = importlib.util.spec_from_file_location("retirement_checker", SCRIPT)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


@pytest.fixture
def sample(tmp_path):
    run(tmp_path, "init", "-q")
    path = "docs/api/capabilities/pdf/example.pdf"
    target = tmp_path / path
    target.parent.mkdir(parents=True)
    target.write_bytes(b"%PDF\x00\xff original evidence")
    run(tmp_path, "add", path)
    run(tmp_path, "-c", "user.name=maintainer", "-c",
        "user.email=23155845+vamseeachanta@users.noreply.github.com", "commit", "-qm", "fixture")
    row = {"path": path, "sha256": hashlib.sha256(target.read_bytes()).hexdigest(),
           "date": "2026-10-17", "reason": "Retired generated print output; cards replace the summary.",
           "disposition": {"kind": "cold-store", "dataset_path": "digitalmodel/retired",
                           "digest_list": "SHA256SUMS.txt"},
           "follow_up": "https://github.com/vamseeachanta/digitalmodel/issues/2687"}
    (tmp_path / "config").mkdir()
    return tmp_path, target, row


def errors(sample, rows):
    repo, _, _ = sample
    (repo / "config/generated_retirements.yml").write_text(yaml.safe_dump({"retirements": rows}))
    rules = yaml.safe_load((ROOT / "config/repo_structure.yml").read_text())
    return checker().check_retirements(repo, rules)


@pytest.mark.parametrize("staged", [False, True])
def test_deletion_requires_matching_committed_digest(sample, staged):
    repo, target, row = sample
    target.unlink()
    if staged:
        run(repo, "add", "-u")
    assert any("generated-artifact-deletion-or-relocation" in e for e in errors(sample, []))
    assert errors(sample, [row]) == []
    row["sha256"] = "0" * 64
    assert any("retirement-digest-mismatch" in e for e in errors(sample, [row]))


def test_tracked_and_reintroduced_retirements_are_refused(sample):
    repo, target, row = sample
    assert any("retirement-entry-for-tracked-path" in e for e in errors(sample, [row]))
    target.unlink()
    run(repo, "add", "-u")
    run(repo, "-c", "user.name=maintainer", "-c",
        "user.email=23155845+vamseeachanta@users.noreply.github.com", "commit", "-qm", "retire")
    assert errors(sample, [row]) == []
    target.write_bytes(b"reintroduced")
    assert any("retirement-entry-for-tracked-path" in e for e in errors(sample, [row]))


@pytest.mark.parametrize("field,value", [
    ("path", "../escape.pdf"), ("path", "/escape.pdf"), ("path", "src/example.py"),
    ("sha256", "ABC"), ("date", "2026-02-30"), ("reason", "TBD"),
    ("follow_up", "https://example.com/issues/1"), ("surprise", "unknown"),
    ("disposition", {"kind": "cold-store", "dataset_path": "../escape", "digest_list": "sum"}),
    ("disposition", {"kind": "cold-store", "dataset_path": "host.example/data", "digest_list": "sum"}),
])
def test_invalid_entries_never_authorize_deletion(sample, field, value):
    _, target, row = sample
    target.unlink()
    row[field] = value
    result = errors(sample, [row])
    assert any("invalid-retirement-entry" in e for e in result)
    assert any("generated-artifact-deletion-or-relocation" in e for e in result)


@pytest.mark.parametrize("field", ["path", "sha256", "date", "reason", "disposition", "follow_up"])
def test_missing_fields_are_rejected(sample, field):
    _, target, row = sample
    target.unlink()
    del row[field]
    assert any("invalid-retirement-entry" in e for e in errors(sample, [row]))


def test_duplicate_paths_and_yaml_keys_are_rejected(sample):
    repo, target, row = sample
    target.unlink()
    assert any("duplicate-retirement-entry" in e for e in errors(sample, [row, row]))
    (repo / "config/generated_retirements.yml").write_text("retirements: []\nretirements: []\n")
    rules = yaml.safe_load((ROOT / "config/repo_structure.yml").read_text())
    assert any("invalid-retirement-entry" in e for e in checker().check_retirements(repo, rules))


def test_rename_retires_source_and_destination_is_classified(sample):
    repo, target, row = sample
    renamed = target.with_name("renamed.pdf")
    run(repo, "mv", row["path"], str(renamed.relative_to(repo)))
    assert any("generated-artifact-deletion-or-relocation" in e for e in errors(sample, []))
    assert errors(sample, [row]) == []
    rules = yaml.safe_load((ROOT / "config/repo_structure.yml").read_text())
    assert checker().check_paths(["unexpected/renamed.pdf"], rules)


def test_retired_path_cannot_remain_in_durable_classification(sample):
    repo, target, row = sample
    target.unlink()
    (repo / "config/generated_retirements.yml").write_text(yaml.safe_dump({"retirements": [row]}))
    rules = yaml.safe_load((ROOT / "config/repo_structure.yml").read_text())
    rules["durable_exceptions"] = [{"pattern": row["path"]}]
    assert any("retired-path-still-allowed" in e for e in checker().check_retirements(repo, rules))
